// execute runs the command dispatch.
func (c *Command) execute(args []string) error {
	// First do partial parsing for known flags to look for --help / -h.
	// Also need to detect if the first positional arg is a subcommand.
	// If so, recurse into that subcommand.
	positional, dashIdx, err := c.parseArgs(args)
