			return sub.execute(append([]string{}, args[indexOfArg(args, subName):]...)[1:])
		}
		// No subcommand found. If the command has a Run, treat as args; otherwise error.
		if c.Run == nil {
			return &ErrUsageRoot{Cmd: c, Msg: fmt.Sprintf("unknown command \"%s\" for \"%s\"", subName, c.FullPath())}
		}
	}

	if c.Run == nil {
		// No command to run: just print help.
		c.printHelp(os.Stdout)
		return nil
	}

	// validate args count
	if c.ExactArgs >= 0 && len(positional) != c.ExactArgs {
		msg := fmt.Sprintf("accepts %d arg(s), received %d", c.ExactArgs, len(positional))
		if c.ArgsErrorMsg != "" {
			msg = c.ArgsErrorMsg + ": " + msg
		}
		return &ErrUsage{Cmd: c, Msg: msg}
	}
	if c.MinArgs >= 0 && len(positional) < c.MinArgs {
		msg := fmt.Sprintf("requires at least %d arg(s), only received %d", c.MinArgs, len(positional))
		if c.ArgsErrorMsg != "" {
			msg = c.ArgsErrorMsg + ": " + msg
		}
		return &ErrUsage{Cmd: c, Msg: msg}
	}

	// Run persistent pre-run (e.g. backend init) if not disabled
	if !c.NoBackend && rootPreRun != nil {
		if err := rootPreRun(c); err != nil {
			return &ErrPlain{Msg: err.Error()}
		}
	}

	if err := c.Run(c, positional); err != nil {
		return &ErrPlain{Msg: err.Error()}
	}
	return nil
}

// indexOfArg returns the index of the first occurrence of arg in args.
func indexOfArg(args []string, arg string) int {
	for i, a := range args {
		if a == arg {
			return i
		}
	}
	return -1
}

// ErrPlain is an error message printed to stderr without usage.
type ErrPlain struct{ Msg string }

func (e *ErrPlain) Error() string { return e.Msg }

// ErrUsageRoot is used when a subcommand-level "unknown command" is produced.
// The help text is NOT appended; just a "Run '... --help' for usage." line.
type ErrUsageRoot struct {
	Cmd *Command
	Msg string
}

func (e *ErrUsageRoot) Error() string { return e.Msg }

var rootPreRun func(c *Command) error
var helpFlag *Flag
var helpFlagCmd *Command

