package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

// FlagType describes the type of a flag argument
type FlagType int

const (
	FlagBool FlagType = iota
	FlagString
	FlagInt
	FlagStringSlice
	FlagStringToString
	FlagCount
)

// Flag represents a single command-line flag definition.
type Flag struct {
	Long      string // long name (e.g. "backend")
	Short     string // short name (e.g. "b"), may be empty
	Type      FlagType
	TypeName  string // displayed type name (e.g. "string", "int"); empty for bools
	Usage     string // help description (may contain backticks for emphasis)
	Default   string // default value shown in help (after "(default ...)"); empty = hide
	NoDefault bool   // when true, don't show a default value
	// Target pointers
	StrVal    *string
	IntVal    *int
	BoolVal   *bool
	SSVal     *map[string]string
	SliceVal  *[]string
	Provided  bool
}

// Command represents a cobra-like command
type Command struct {
	Name     string
	Use      string // usage line after "chamber" prefix
	Aliases  []string
	Short    string // short description
	Long     string // long description (optional, falls back to Short)
	Example  string
	Flags    []*Flag
	Subs     []*Command
	Parent   *Command
	Run      func(cmd *Command, args []string) error

	// argument validation
	ExactArgs    int // -1 = not used
	MinArgs      int // -1 = not used
	ArgsErrorMsg string // custom message prefix for argument errors

	Hidden bool

	// whether to run PersistentPreRun
	NoBackend bool
}

func newCommand(name string) *Command {
	return &Command{Name: name, ExactArgs: -1, MinArgs: -1}
}

// FullPath returns the space-separated path from the root to this command.
func (c *Command) FullPath() string {
	parts := []string{}
	for cur := c; cur != nil; cur = cur.Parent {
		parts = append([]string{cur.Name}, parts...)
	}
	return strings.Join(parts, " ")
}

// rootAncestor returns the topmost ancestor.
func (c *Command) rootAncestor() *Command {
	cur := c
	for cur.Parent != nil {
		cur = cur.Parent
	}
	return cur
}

// hasRunnableChildren returns true if this command has visible subcommands.
func (c *Command) hasRunnableChildren() bool {
	for _, sub := range c.Subs {
		if !sub.Hidden {
			return true
		}
	}
	return false
}

// find a subcommand by exact name or alias
func (c *Command) findSub(name string) *Command {
	for _, sub := range c.Subs {
		if sub.Name == name {
			return sub
		}
		for _, a := range sub.Aliases {
			if a == name {
				return sub
			}
		}
	}
	return nil
}

// findFlag searches this command plus persistent (global) flags.
func (c *Command) findFlag(name string, short bool) *Flag {
	for cur := c; cur != nil; cur = cur.Parent {
		for _, f := range cur.Flags {
			if short {
				if f.Short == name {
					return f
				}
			} else {
				if f.Long == name {
					return f
				}
			}
		}
	}
	return nil
}

// applyFlag parses a value string into the flag's target.
func (f *Flag) applyFlag(value string) error {
	switch f.Type {
	case FlagBool:
		// should not be called - handled specially
		v, err := strconv.ParseBool(value)
		if err != nil {
			return fmt.Errorf("invalid argument %q for %q flag: %v", value, f.flagDisplay(), err)
		}
		*f.BoolVal = v
	case FlagString:
		*f.StrVal = value
	case FlagInt:
		v, err := strconv.ParseInt(value, 10, 64)
		if err != nil {
			return fmt.Errorf("invalid argument %q for %q flag: strconv.ParseInt: parsing %q: invalid syntax", value, f.flagDisplay(), value)
		}
		*f.IntVal = int(v)
	case FlagStringSlice:
		*f.SliceVal = append(*f.SliceVal, value)
	case FlagStringToString:
		// value is comma-separated list of k=v
		for _, pair := range splitStringToStringList(value) {
			idx := strings.Index(pair, "=")
			if idx < 0 {
				return fmt.Errorf("invalid argument %q for %q flag: %s must be formatted as key=value", value, f.flagDisplay(), pair)
			}
			(*f.SSVal)[pair[:idx]] = pair[idx+1:]
		}
	}
	f.Provided = true
	return nil
}

// splitStringToStringList splits a string by commas respecting nothing special.
func splitStringToStringList(s string) []string {
	if s == "" {
		return nil
	}
	return strings.Split(s, ",")
}

func (f *Flag) flagDisplay() string {
	if f.Short != "" {
		return fmt.Sprintf("-%s, --%s", f.Short, f.Long)
	}
	return "--" + f.Long
}

// Parses arguments for the given command. Returns positional args.
// Flags are consumed. Unknown flags/commands are returned as errors.
// When "--" is encountered, remaining args are treated as positional
// (without further flag parsing), and for `exec` specifically the caller
// uses them as the child command arguments.
func (c *Command) parseArgs(args []string) (positional []string, dashIndex int, err error) {
	dashIndex = -1
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			dashIndex = len(positional)
			positional = append(positional, args[i+1:]...)
			break
		}
		if strings.HasPrefix(a, "--") && len(a) > 2 {
			name := a[2:]
			eqIdx := strings.Index(name, "=")
			var value string
			hasValue := false
			if eqIdx >= 0 {
				value = name[eqIdx+1:]
				name = name[:eqIdx]
				hasValue = true
			}
			flag := c.findFlag(name, false)
			if flag == nil {
				return nil, -1, fmt.Errorf("unknown flag: --%s", name)
			}
			if flag.Type == FlagBool {
				if hasValue {
					v, perr := strconv.ParseBool(value)
					if perr != nil {
						return nil, -1, fmt.Errorf("invalid argument %q for %q flag: %v", value, flag.flagDisplay(), perr)
					}
					*flag.BoolVal = v
				} else {
					*flag.BoolVal = true
				}
				flag.Provided = true
				i++
				continue
			}
			if !hasValue {
				if i+1 >= len(args) {
					return nil, -1, fmt.Errorf("flag needs an argument: --%s", name)
				}
				value = args[i+1]
				i++
			}
			if err := flag.applyFlag(value); err != nil {
				return nil, -1, err
			}
			i++
			continue
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 && a != "-" {
			// short flag block
			j := 1
			for j < len(a) {
				short := string(a[j])
				flag := c.findFlag(short, true)
				if flag == nil {
					return nil, -1, fmt.Errorf("unknown shorthand flag: %q in -%s", short, a[1:])
				}
				if flag.Type == FlagBool {
					*flag.BoolVal = true
					flag.Provided = true
					j++
					continue
				}
				// needs value. The remainder of this token is the value if present,
				// optionally after '=', else the next arg.
				rest := a[j+1:]
				if strings.HasPrefix(rest, "=") {
					rest = rest[1:]
				}
				var value string
				if rest != "" {
					value = rest
				} else {
					if i+1 >= len(args) {
						return nil, -1, fmt.Errorf("flag needs an argument: %q in -%s", short, a[1:])
					}
					value = args[i+1]
					i++
				}
				if err := flag.applyFlag(value); err != nil {
					return nil, -1, err
				}
				break
			}
			i++
			continue
		}
		positional = append(positional, a)
		i++
	}
	return positional, dashIndex, nil
}

// formatFlagsSection produces the "Flags:" block in the style cobra uses.
// Includes only flags local to this command (non-persistent).
func (c *Command) formatFlagsSection(persistent bool) string {
	var flags []*Flag
	if persistent {
		// Collect persistent (parent chain) flags.
		for cur := c.Parent; cur != nil; cur = cur.Parent {
			flags = append(flags, cur.Flags...)
		}
	} else {
		// Local flags plus the -h/--help flag.
		flags = append(flags, c.Flags...)
	}
	if len(flags) == 0 {
		return ""
	}
	// Sort alphabetically by long name.
	// Stable sort by long name (lowercased).
	sorted := make([]*Flag, len(flags))
	copy(sorted, flags)
	sortFlags(sorted)

	// Calculate column widths.
	// Column 1: "  -x, --long <type>" or "      --long <type>"
	prefixes := make([]string, len(sorted))
	for i, f := range sorted {
		prefixes[i] = f.prefixString()
	}
	maxLen := 0
	for _, p := range prefixes {
		if len(p) > maxLen {
			maxLen = len(p)
		}
	}
	// Padding: 3 spaces after the longest prefix
	colWidth := maxLen + 3

	var sb strings.Builder
	if persistent {
		sb.WriteString("Global Flags:\n")
	} else {
		sb.WriteString("Flags:\n")
	}
	for i, f := range sorted {
		line := prefixes[i]
		pad := colWidth - len(line)
		if pad < 1 {
			pad = 1
		}
		sb.WriteString(line)
		sb.WriteString(strings.Repeat(" ", pad))
		// description lines, subsequent lines use the same column
		descLines := strings.Split(f.fullDescription(), "\n")
		for j, dl := range descLines {
			if j == 0 {
				sb.WriteString(dl)
				sb.WriteString("\n")
			} else {
				sb.WriteString(strings.Repeat(" ", colWidth))
				sb.WriteString(dl)
				sb.WriteString("\n")
			}
		}
	}
	return sb.String()
}

// prefixString returns the left column before the description, e.g. "  -b, --backend string".
func (f *Flag) prefixString() string {
	var sb strings.Builder
	if f.Short != "" {
		sb.WriteString("  -")
		sb.WriteString(f.Short)
		sb.WriteString(", --")
		sb.WriteString(f.Long)
	} else {
		sb.WriteString("      --")
		sb.WriteString(f.Long)
	}
	if f.TypeName != "" {
		sb.WriteString(" ")
		sb.WriteString(f.TypeName)
	}
	return sb.String()
}

// fullDescription returns the help description + default text if applicable.
func (f *Flag) fullDescription() string {
	desc := f.Usage
	if !f.NoDefault && f.Default != "" {
		desc += fmt.Sprintf(" (default %s)", f.Default)
	}
	return desc
}

// sortFlags sorts alphabetically by long name.
func sortFlags(flags []*Flag) {
	// stable insertion sort
	for i := 1; i < len(flags); i++ {
		for j := i; j > 0 && flags[j-1].Long > flags[j].Long; j-- {
			flags[j-1], flags[j] = flags[j], flags[j-1]
		}
	}
}

// helpText builds the help output for a command.
func (c *Command) helpText() string {
	var sb strings.Builder
	longOrShort := c.Long
	if longOrShort == "" {
		longOrShort = c.Short
	}
	sb.WriteString(longOrShort)
	sb.WriteString("\n\n")

	sb.WriteString("Usage:\n")
	if c.Run != nil {
		sb.WriteString("  " + c.Use + "\n")
	}
	if c.hasRunnableChildren() {
		sb.WriteString("  " + c.FullPath() + " [command]\n")
	}
	sb.WriteString("\n")

	if len(c.Aliases) > 0 {
		sb.WriteString("Aliases:\n")
		sb.WriteString("  " + c.Name)
		for _, a := range c.Aliases {
			sb.WriteString(", " + a)
		}
		sb.WriteString("\n\n")
	}

	if c.Example != "" {
		sb.WriteString("Examples:\n")
		sb.WriteString(c.Example)
		if !strings.HasSuffix(c.Example, "\n") {
			sb.WriteString("\n")
		}
		sb.WriteString("\n")
	}

	if c.hasRunnableChildren() {
		sb.WriteString("Available Commands:\n")
		maxLen := 0
		for _, sub := range c.Subs {
			if sub.Hidden {
				continue
			}
			if len(sub.Name) > maxLen {
				maxLen = len(sub.Name)
			}
		}
		for _, sub := range c.Subs {
			if sub.Hidden {
				continue
			}
			pad := maxLen - len(sub.Name) + 1
			sb.WriteString("  " + sub.Name + strings.Repeat(" ", pad) + " " + sub.Short + "\n")
		}
		sb.WriteString("\n")
	}

	// local flags (always include -h)
	localFlagsText := c.formatFlagsSection(false)
	if localFlagsText != "" {
		sb.WriteString(localFlagsText)
		sb.WriteString("\n")
	}

	// global (persistent) flags from ancestors
	if c.Parent != nil {
		persistentText := c.formatFlagsSection(true)
		if persistentText != "" {
			sb.WriteString(persistentText)
		}
	}

	if c.hasRunnableChildren() {
		sb.WriteString(fmt.Sprintf("\nUse \"%s [command] --help\" for more information about a command.\n", c.FullPath()))
	}

	return sb.String()
}

// printHelp writes the help text.
func (c *Command) printHelp(w io.Writer) {
	fmt.Fprint(w, c.helpText())
}

// ErrUsage is returned when the usage should also be printed on stderr after an error.
type ErrUsage struct {
	Cmd *Command
	Msg string
}

func (e *ErrUsage) Error() string { return e.Msg }

// execute runs the command dispatch.
func (c *Command) execute(args []string) error {
	// First do partial parsing for known flags to look for --help / -h.
	// Also need to detect if the first positional arg is a subcommand.
	// If so, recurse into that subcommand.
	positional, dashIdx, err := c.parseArgs(args)
	_ = dashIdx
	if err != nil {
		return &ErrUsage{Cmd: c, Msg: err.Error()}
	}

	// If --help was set, print help.
	if helpFlag != nil && helpFlag.Provided && helpFlagCmd == c {
		c.printHelp(os.Stdout)
		helpFlag.Provided = false
		return nil
	}

	// Check for a subcommand as the first positional argument.
	if len(positional) > 0 && c.hasRunnableChildren() {
		subName := positional[0]
		sub := c.findSub(subName)
		if sub != nil {
			return sub.execute(append([]string{}, args[indexOfArg(args, subName):]...)[1:])
		}
		// No subcommand found. If the command has a Run, treat as args; otherwise error.
		if c.Run == nil {
			return &ErrUsageRoot{Cmd: c, Msg: fmt.Sprintf("unknown command \"%s\" for \"%s\"", subName, c.FullPath())}
		}
	}

	if c.Run == nil {
		// No command to run: just print help.
		c.printHelp(os.Stdout)
		return nil
	}

	// validate args count
	if c.ExactArgs >= 0 && len(positional) != c.ExactArgs {
		msg := fmt.Sprintf("accepts %d arg(s), received %d", c.ExactArgs, len(positional))
		if c.ArgsErrorMsg != "" {
			msg = c.ArgsErrorMsg + ": " + msg
		}
		return &ErrUsage{Cmd: c, Msg: msg}
	}
	if c.MinArgs >= 0 && len(positional) < c.MinArgs {
		msg := fmt.Sprintf("requires at least %d arg(s), only received %d", c.MinArgs, len(positional))
		if c.ArgsErrorMsg != "" {
			msg = c.ArgsErrorMsg + ": " + msg
		}
		return &ErrUsage{Cmd: c, Msg: msg}
	}

	// Run persistent pre-run (e.g. backend init) if not disabled
	if !c.NoBackend && rootPreRun != nil {
		if err := rootPreRun(c); err != nil {
			return &ErrPlain{Msg: err.Error()}
		}
	}

	if err := c.Run(c, positional); err != nil {
		return &ErrPlain{Msg: err.Error()}
	}
	return nil
}

// indexOfArg returns the index of the first occurrence of arg in args.
func indexOfArg(args []string, arg string) int {
	for i, a := range args {
		if a == arg {
			return i
		}
	}
	return -1
}

// ErrPlain is an error message printed to stderr without usage.
type ErrPlain struct{ Msg string }

func (e *ErrPlain) Error() string { return e.Msg }

// ErrUsageRoot is used when a subcommand-level "unknown command" is produced.
// The help text is NOT appended; just a "Run '... --help' for usage." line.
type ErrUsageRoot struct {
	Cmd *Command
	Msg string
}

func (e *ErrUsageRoot) Error() string { return e.Msg }

var rootPreRun func(c *Command) error
var helpFlag *Flag
var helpFlagCmd *Command

