var (
	rootCmd *Command
)

func setupGlobalFlags(c *Command) {
	c.Flags = append(c.Flags,
		newStringFlag("backend", "b", &globals.Backend),
		newStringFlag("backend-s3-bucket", "", &globals.BackendS3Bucket),
		newStringFlag("kms-key-alias", "", &globals.KMSKeyAlias),
		newIntFlag("retries", "r", &globals.Retries),
		newStringFlag("retry-mode", "", &globals.RetryMode),
		newBoolFlag("verbose", "", &globals.Verbose),
	)
}

func buildCommands() *Command {
	root := &Command{
		Name:    "chamber",
		UseLine: "chamber [command]",
		Help:    mustHelp("root"),
	}
	setupGlobalFlags(root)

	// version
	version := &Command{
		Name:      "version",
		UseLine:   "chamber version [flags]",
		Help:      mustHelp("version"),
		Parent:    root,
		NoBackend: true,
		ExactArgs: 0,
		Run: func(cmd *Command, args, rest []string, hasSep bool) error {
			fmt.Println("chamber dev")
			return nil
		},
	}
	root.Subs = append(root.Subs, version)

	// help
	helpCmd := &Command{
		Name:      "help",
		UseLine:   "chamber help [command] [flags]",
		Help:      mustHelp("help"),
		Parent:    root,
		NoBackend: true,
		Run: func(cmd *Command, args, rest []string, hasSep bool) error {
			// If args given, try to find that subcommand and show its help.
			cur := root
			for _, a := range args {
				sub := cur.findSub(a)
				if sub == nil {
					// Unknown help topic: show message + root help to stdout
					fmt.Fprintf(os.Stdout, "Unknown help topic [`%s`]\n", a)
					fmt.Fprint(os.Stdout, strings.TrimPrefix(root.Help, "CLI for storing secrets\n\n"))
					return nil
				}
				cur = sub
			}
			fmt.Fprint(os.Stdout, cur.Help)
			return nil
		},
	}
	root.Subs = append(root.Subs, helpCmd)

	// completion
	completion := &Command{
		Name:      "completion",
		UseLine:   "chamber completion [command]",
		Help:      mustHelp("completion"),
		Parent:    root,
		NoBackend: true,
	}
	for _, shell := range []string{"bash", "zsh", "fish", "powershell"} {
		shellName := shell
		noDesc := false
		sub := &Command{
			Name:      shellName,
			Parent:    completion,
			NoBackend: true,
			Help:      mustHelp("completion_" + shellName),
			Flags: []*Flag{
				newBoolFlag("no-descriptions", "", &noDesc),
			},
			ExactArgs: 0,
		}
		sub.Flags[0].BoolVal = new(bool)
		noDescPtr := sub.Flags[0].BoolVal
		sub.Run = func(cmd *Command, args, rest []string, hasSep bool) error {
			name := "gen_" + shellName
			if *noDescPtr {
				name += "_nodesc"
			}
			fmt.Fprint(os.Stdout, mustHelp(name))
			return nil
		}
		completion.Subs = append(completion.Subs, sub)
	}
	root.Subs = append(root.Subs, completion)

	// delete
	deleteExact := false
	del := &Command{
		Name:      "delete",
		UseLine:   "chamber delete <service> <key> [flags]",
		Help:      mustHelp("delete"),
		Parent:    root,
		ExactArgs: 2,
		Flags: []*Flag{
			newBoolFlag("exact-key", "", &deleteExact),
		},
		Run: func(cmd *Command, args, rest []string, hasSep bool) error {
			return nullErr("Not implemented for Null Store")
		},
	}
	root.Subs = append(root.Subs, del)

	// env
	envPreserve := false
	envEscape := false
	envCmd := &Command{
		Name:      "env",
		UseLine:   "chamber env <service> [flags]",
		Help:      mustHelp("env"),
		Parent:    root,
		ExactArgs: 1,
		Flags: []*Flag{
			newBoolFlag("preserve-case", "p", &envPreserve),
			newBoolFlag("escape-strings", "e", &envEscape),
		},
		Run: func(cmd *Command, args, rest []string, hasSep bool) error {
			if globals.Backend == "null" {
				return nil
			}
			return backendFailListErr()
		},
	}
	root.Subs = append(root.Subs, envCmd)

	// exec
	execStrict := false
	execPristine := false
	execStrictVal := "chamberme"
	execCmd := &Command{
		Name:    "exec",
		UseLine: "chamber exec <service...> -- <command> [<arg...>] [flags]",
		Help:    mustHelp("exec"),
		Parent:  root,
		Flags: []*Flag{
			newBoolFlag("strict", "", &execStrict),
			newBoolFlag("pristine", "", &execPristine),
			newStringFlag("strict-value", "", &execStrictVal),
		},
		Run: func(cmd *Command, args, rest []string, hasSep bool) error {
			return doExec(args, rest, hasSep, &execStrict, &execPristine, &execStrictVal)
		},
	}
	root.Subs = append(root.Subs, execCmd)

	// export
	expFormat := "json"
	expOut := ""
	exp := &Command{
		Name:    "export",
		UseLine: "chamber export <service...> [flags]",
		Help:    mustHelp("export"),
		Parent:  root,
		MinArgs: 1,
		Flags: []*Flag{
			newStringFlag("format", "f", &expFormat),
			newStringFlag("output-file", "o", &expOut),
		},
		Run: func(cmd *Command, args, rest []string, hasSep bool) error {
			return doExport(args, &expFormat, &expOut)
		},
	}
	root.Subs = append(root.Subs, exp)

	// find
	findByValue := false
	findCmd := &Command{
		Name:      "find",
		UseLine:   "chamber find <secret name> [flags]",
		Help:      mustHelp("find"),
		Parent:    root,
		ExactArgs: 1,
		Flags: []*Flag{
			newBoolFlag("by-value", "v", &findByValue),
		},
		Run: func(cmd *Command, args, rest []string, hasSep bool) error {
			return doFind(args, &findByValue)
		},
	}
	root.Subs = append(root.Subs, findCmd)

	// history
	hist := &Command{
		Name:      "history",
		UseLine:   "chamber history <service> <key> [flags]",
		Help:      mustHelp("history"),
		Parent:    root,
		ExactArgs: 2,
		Run: func(cmd *Command, args, rest []string, hasSep bool) error {
			return doHistory(args)
		},
	}
	root.Subs = append(root.Subs, hist)

	// import
	normalizeKeys := false
	importCmd := &Command{
		Name:      "import",
		UseLine:   "chamber import <service> <file|-> [flags]",
		Help:      mustHelp("import"),
		Parent:    root,
		ExactArgs: 2,
		Flags: []*Flag{
			newBoolFlag("normalize-keys", "", &normalizeKeys),
		},
		Run: func(cmd *Command, args, rest []string, hasSep bool) error {
			return doImport(args, &normalizeKeys)
		},
	}
	root.Subs = append(root.Subs, importCmd)

	// list
	lsExpand, lsTime, lsUser, lsVersion := false, false, false, false
	lsCmd := &Command{
		Name:      "list",
		UseLine:   "chamber list <service> [flags]",
		Help:      mustHelp("list"),
		Parent:    root,
		ExactArgs: 1,
		Flags: []*Flag{
			newBoolFlag("expand", "e", &lsExpand),
			newBoolFlag("time", "t", &lsTime),
			newBoolFlag("user", "u", &lsUser),
			newBoolFlag("version", "v", &lsVersion),
		},
		Run: func(cmd *Command, args, rest []string, hasSep bool) error {
			return doList(args, &lsExpand)
		},
	}
	root.Subs = append(root.Subs, lsCmd)

	// list-services
	lsSecrets := false
	lsSvc := &Command{
		Name:      "list-services",
		UseLine:   "chamber list-services <service> [flags]",
		Help:      mustHelp("list-services"),
		Parent:    root,
		ExactArgs: 1,
		Flags: []*Flag{
			newBoolFlag("secrets", "s", &lsSecrets),
		},
		Run: func(cmd *Command, args, rest []string, hasSep bool) error {
			return doListServices(args, &lsSecrets)
		},
	}
	root.Subs = append(root.Subs, lsSvc)

	// read
	rdQuiet := false
	rdVersion := -1
	rdCmd := &Command{
		Name:      "read",
		UseLine:   "chamber read <service> <key> [flags]",
		Help:      mustHelp("read"),
		Parent:    root,
		ExactArgs: 2,
		Flags: []*Flag{
			newBoolFlag("quiet", "q", &rdQuiet),
			newIntFlag("version", "v", &rdVersion),
		},
		Run: func(cmd *Command, args, rest []string, hasSep bool) error {
			return fmt.Errorf("Failed to read: Not implemented for Null Store")
		},
	}
	root.Subs = append(root.Subs, rdCmd)

	// tag (+ sub)
	tagCmd := &Command{
		Name:    "tag",
		UseLine: "chamber tag [command]",
		Help:    mustHelp("tag"),
		Parent:  root,
	}
	tagRead := &Command{
		Name:      "read",
		UseLine:   "chamber tag read <service> <key> [flags]",
		Help:      mustHelp("tag_read"),
		Parent:    tagCmd,
		ExactArgs: 2,
		Run: func(cmd *Command, args, rest []string, hasSep bool) error {
			return fmt.Errorf("Failed to read tags: Not implemented for Null Store")
		},
	}
	tagWriteDelOthers := false
	tagWrite := &Command{
		Name:    "write",
		UseLine: "chamber tag write <service> <key> <tag>... [flags]",
		Help:    mustHelp("tag_write"),
		Parent:  tagCmd,
		MinArgs: 3,
		Flags: []*Flag{
			newBoolFlag("delete-other-tags", "", &tagWriteDelOthers),
		},
		Run: func(cmd *Command, args, rest []string, hasSep bool) error {
			return fmt.Errorf("Failed to write tags: Not implemented for Null Store")
		},
	}
	tagDelete := &Command{
		Name:    "delete",
		UseLine: "chamber tag delete <service> <key> <tag key>... [flags]",
		Help:    mustHelp("tag_delete"),
		Parent:  tagCmd,
		MinArgs: 3,
		Run: func(cmd *Command, args, rest []string, hasSep bool) error {
			return fmt.Errorf("Failed to delete tags: Not implemented for Null Store")
		},
	}
	tagCmd.Subs = []*Command{tagDelete, tagRead, tagWrite}
	root.Subs = append(root.Subs, tagCmd)

	// write
	wrSingleline := false
	wrSkip := false
	wrTags := map[string]string{}
	wrCmd := &Command{
		Name:      "write",
		UseLine:   "chamber write <service> <key> [--] <value|-> [flags]",
		Help:      mustHelp("write"),
		Parent:    root,
		ExactArgs: 3,
		Flags: []*Flag{
			newBoolFlag("singleline", "s", &wrSingleline),
			newBoolFlag("skip-unchanged", "", &wrSkip),
			newStringToStringFlag("tags", "t", &wrTags),
		},
		Run: func(cmd *Command, args, rest []string, hasSep bool) error {
			if len(wrTags) > 0 {
				return fmt.Errorf("Failed to write secret: WriteWithTags is not implemented for Null Store")
			}
			return fmt.Errorf("Failed to write secret: Write is not implemented for Null Store")
		},
	}
	root.Subs = append(root.Subs, wrCmd)

	// Hidden: __complete
	// We don't implement this behavior precisely (mostly unused in tests).
	complHidden := &Command{
		Name:    "__complete",
		Aliases: []string{"__completeNoDesc"},
		UseLine: "chamber __complete [command-line]",
		Parent:  root,
		NoBackend: true,
		MinArgs: 1,
		Run: func(cmd *Command, args, rest []string, hasSep bool) error {
			return nil
		},
	}
	complHidden.Help = "" // not needed
	root.Subs = append(root.Subs, complHidden)

	// Sort subs alphabetically for help (root only needs alphabetical help display
	// but we've been adding in order; let me preserve order for help).
	// Actually cobra sorts alphabetically. Let me sort.
	sortSubs(root)
	sortSubs(tagCmd)
	sortSubs(completion)

	return root
}

func sortSubs(c *Command) {
	sort.SliceStable(c.Subs, func(i, j int) bool {
		// Hidden items go to end or omitted from help.
		return c.Subs[i].Name < c.Subs[j].Name
	})
}

// ---- Command implementations ----

func nullErr(msg string) error {
	return fmt.Errorf("%s", msg)
}

// backendFailListErr constructs the list-contents failure for AWS-like backends.
func backendFailListErr() error {
	b := strings.ToUpper(globals.Backend)
	return fmt.Errorf("Failed to list store contents: could not initialize %s backend", b)
}

func doList(args []string, expand *bool) error {
	if globals.Backend == "null" {
		if *expand {
			fmt.Println("Key\tVersion\t\tLastModified\tUser\tValue")
		} else {
			fmt.Println("Key\tVersion\t\tLastModified\tUser")
		}
		return nil
	}
	return backendFailListErr()
}

func doListServices(args []string, secrets *bool) error {
	if globals.Backend == "null" {
		fmt.Println("Service")
		return nil
	}
	return backendFailListErr()
}

func doFind(args []string, byValue *bool) error {
	if globals.Backend == "null" {
		if *byValue {
			fmt.Println("Service\t\tKey")
		} else {
			fmt.Println("Service")
		}
		return nil
	}
	return backendFailListErr()
}

func doHistory(args []string) error {
	if globals.Backend == "null" {
		fmt.Println("Event\tVersion\t\tDate\tUser")
		return nil
	}
	return backendFailListErr()
}

func doExport(args []string, format, out *string) error {
	f := strings.ToLower(*format)
	var content string
	switch f {
	case "json":
		content = "{}\n"
	case "yaml":
		content = "{}\n"
	case "java-properties", "csv", "tsv", "dotenv", "tfvars":
		content = ""
	default:
		return fmt.Errorf("Unable to export parameters: Unsupported export format: %s", *format)
	}
	if globals.Backend != "null" {
		return backendFailListErr()
	}
	if *out != "" {
		return os.WriteFile(*out, []byte(content), 0644)
	}
	fmt.Print(content)
	return nil
}

func doExec(services, rest []string, hasSep bool, strict, pristine *bool, strictVal *string) error {
	if globals.Backend != "null" {
		return backendFailListErr()
	}
	// Null backend: no secrets. Strict mode checks: no env vars equal strictVal (unless also in secrets = empty).
	if *strict {
		// Fail on any env var whose value equals strictVal.
		var matched []string
		for _, ev := range os.Environ() {
			eq := strings.Index(ev, "=")
			name, val := ev[:eq], ev[eq+1:]
			if val == *strictVal {
				matched = append(matched, name)
			}
		}
		if len(matched) > 0 {
			// Sorted? Let's match format: one var at a time reported.
			sort.Strings(matched)
			return fmt.Errorf("parent env was expecting %s=%s, but was not in store", matched[0], *strictVal)
		}
	}
	// Execute the command
	if len(rest) == 0 {
		return fmt.Errorf("must specify command to run. See usage: requires at least 1 arg(s), only received 0")
	}
	return runChild(rest, *pristine)
}

func doImport(args []string, normalize *bool) error {
	// args[0] = service, args[1] = file or -
	var data []byte
	if args[1] == "-" {
		d, err := io.ReadAll(os.Stdin)
		if err != nil {
			return fmt.Errorf("Failed to read stdin: %v", err)
		}
		data = d
	} else {
		d, err := os.ReadFile(args[1])
		if err != nil {
			return fmt.Errorf("Failed to open file: %s", err.Error())
		}
		data = d
	}
	// Try to parse as JSON or YAML (simple map[string]string).
	kv, perr := parseJSONOrYAMLMap(data)
	if perr != nil {
		return fmt.Errorf("Failed to decode input as json: %v", perr)
	}
	if globals.Backend != "null" {
		return backendFailListErr()
	}
	// null backend: 0 secrets imported (it says Successfully imported)?
	// If there are any entries, we'd have to try writing, which fails.
	if len(kv) == 0 {
		fmt.Println("Successfully imported 0 secrets")
		return nil
	}
	return fmt.Errorf("Failed to write secret: Write is not implemented for Null Store")
}

