// ----- Flag definitions -----

type FlagKind int

const (
	KBool FlagKind = iota
	KString
	KInt
	KStringToString
	KStringArray
)

type Flag struct {
	Long      string
	Short     string
	Kind      FlagKind
	StrVal    *string
	IntVal    *int
	BoolVal   *bool
	MapVal    *map[string]string
	ArrVal    *[]string
	Provided  bool
}

func newStringFlag(long, short string, dst *string) *Flag {
	return &Flag{Long: long, Short: short, Kind: KString, StrVal: dst}
}
func newBoolFlag(long, short string, dst *bool) *Flag {
	return &Flag{Long: long, Short: short, Kind: KBool, BoolVal: dst}
}
func newIntFlag(long, short string, dst *int) *Flag {
	return &Flag{Long: long, Short: short, Kind: KInt, IntVal: dst}
}
func newStringToStringFlag(long, short string, dst *map[string]string) *Flag {
	return &Flag{Long: long, Short: short, Kind: KStringToString, MapVal: dst}
}
func newStringArrayFlag(long, short string, dst *[]string) *Flag {
	return &Flag{Long: long, Short: short, Kind: KStringArray, ArrVal: dst}
}

// ----- Command definition -----

type Command struct {
	Name    string
	Aliases []string
	UseLine string // right-hand part shown in Usage (e.g. "chamber list <service> [flags]")
	Help    string // embedded help text
	Parent  *Command
	Subs    []*Command
	Flags   []*Flag

	// Argument validation
	ExactArgs       int // -1 not used
	MinArgs         int // -1 not used
	ArgsErrPrefix   string

	// Command logic (nil = print help)
	Run func(cmd *Command, args []string, rest []string, hasSep bool) error

	// When true, do not initialize the backend (e.g. version, completion)
	NoBackend bool

	// When true, the help does not append "Usage:" after errors (Help already contains it).
	UseLineIsInHelp bool
}

func (c *Command) FullPath() string {
	if c.Parent == nil {
		return c.Name
	}
	return c.Parent.FullPath() + " " + c.Name
}

func (c *Command) findSub(name string) *Command {
	for _, s := range c.Subs {
		if s.Name == name {
			return s
		}
		for _, a := range s.Aliases {
			if a == name {
				return s
			}
		}
	}
	return nil
}

func (c *Command) findFlag(long string, short bool) *Flag {
	for cur := c; cur != nil; cur = cur.Parent {
		for _, f := range cur.Flags {
			if short {
				if f.Short == long {
					return f
				}
			} else {
				if f.Long == long {
					return f
				}
			}
		}
	}
	return nil
}

// ---- Flag parsing ----

func parseFlagValue(f *Flag, raw string, flagDisplay string) error {
	switch f.Kind {
	case KBool:
		v, err := strconv.ParseBool(raw)
		if err != nil {
			return fmt.Errorf("invalid argument %q for %q flag: strconv.ParseBool: parsing %q: invalid syntax", raw, flagDisplay, raw)
		}
		*f.BoolVal = v
	case KString:
		*f.StrVal = raw
	case KInt:
		n, err := strconv.ParseInt(raw, 10, 64)
		if err != nil {
			return fmt.Errorf("invalid argument %q for %q flag: strconv.ParseInt: parsing %q: invalid syntax", raw, flagDisplay, raw)
		}
		*f.IntVal = int(n)
	case KStringArray:
		*f.ArrVal = append(*f.ArrVal, raw)
	case KStringToString:
		for _, pair := range splitCSV(raw) {
			idx := strings.Index(pair, "=")
			if idx < 0 {
				return fmt.Errorf("invalid argument %q for %q flag: %s must be formatted as key=value", raw, flagDisplay, pair)
			}
			if *f.MapVal == nil {
				*f.MapVal = map[string]string{}
			}
			(*f.MapVal)[pair[:idx]] = pair[idx+1:]
		}
	}
	f.Provided = true
	return nil
}

// splitCSV splits by commas. Empty string -> nil.
func splitCSV(s string) []string {
	if s == "" {
		return nil
	}
	return strings.Split(s, ",")
}

func displayFlag(f *Flag) string {
	if f.Short != "" {
		return fmt.Sprintf("-%s, --%s", f.Short, f.Long)
	}
	return "--" + f.Long
}

// ---- Argument parsing ----

// parseArgs consumes args, extracting flag values, and returns the positional args
// plus anything after "--" (if encountered) and whether "--" was seen.
// helpRequested indicates whether -h/--help was specified for this command (or a parent).
func (c *Command) parseArgs(args []string) (positional, after []string, hasSep bool, helpRequested bool, err error) {
	i := 0
	for i < len(args) {
		a := args[i]
		if a == "--" {
			hasSep = true
			after = append([]string{}, args[i+1:]...)
			break
		}
		if strings.HasPrefix(a, "--") && len(a) > 2 {
			name := a[2:]
			eq := strings.Index(name, "=")
			var value string
			hasValue := false
			if eq >= 0 {
				value = name[eq+1:]
				name = name[:eq]
				hasValue = true
			}
			if name == "help" {
				helpRequested = true
				i++
				continue
			}
			flag := c.findFlag(name, false)
			if flag == nil {
				err = fmt.Errorf("unknown flag: --%s", name)
				return
			}
			if flag.Kind == KBool {
				if hasValue {
					v, perr := strconv.ParseBool(value)
					if perr != nil {
						err = fmt.Errorf("invalid argument %q for %q flag: strconv.ParseBool: parsing %q: invalid syntax", value, displayFlag(flag), value)
						return
					}
					*flag.BoolVal = v
				} else {
					*flag.BoolVal = true
				}
				flag.Provided = true
				i++
				continue
			}
			if !hasValue {
				if i+1 >= len(args) {
					err = fmt.Errorf("flag needs an argument: --%s", name)
					return
				}
				value = args[i+1]
				i++
			}
			if perr := parseFlagValue(flag, value, displayFlag(flag)); perr != nil {
				err = perr
				return
			}
			i++
			continue
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 && a != "-" {
			j := 1
			for j < len(a) {
				sh := string(a[j])
				if sh == "h" {
					helpRequested = true
					j++
					continue
				}
				flag := c.findFlag(sh, true)
				if flag == nil {
					err = fmt.Errorf("unknown shorthand flag: %q in -%s", sh, a[1:])
					return
				}
				if flag.Kind == KBool {
					*flag.BoolVal = true
					flag.Provided = true
					j++
					continue
				}
				// needs value
				rest := a[j+1:]
				if strings.HasPrefix(rest, "=") {
					rest = rest[1:]
				}
				var value string
				if rest != "" {
					value = rest
				} else {
					if i+1 >= len(args) {
						err = fmt.Errorf("flag needs an argument: %q in -%s", sh, a[1:])
						return
					}
					value = args[i+1]
					i++
				}
				if perr := parseFlagValue(flag, value, displayFlag(flag)); perr != nil {
					err = perr
					return
				}
				break
			}
			i++
			continue
		}
		positional = append(positional, a)
		i++
	}
	return
}

// ---- Dispatch ----

// runCommand walks subcommands and dispatches.
func runCommand(cmd *Command, args []string) int {
	// Extract subcommand path greedily
	for {
		if len(args) > 0 {
			sub := cmd.findSub(args[0])
			if sub != nil {
				cmd = sub
				args = args[1:]
				continue
			}
		}
		break
	}

	positional, after, hasSep, helpReq, err := cmd.parseArgs(args)
	if err != nil {
		fmt.Fprintln(os.Stderr, "Error: "+err.Error())
		cmd.printUsageAndFlags(os.Stderr)
		return 1
	}

	if helpReq {
		fmt.Fprint(os.Stdout, cmd.Help)
		return 0
	}

	// If this is a branch command (no Run) and first positional is an unknown subcommand, err.
	if cmd.Run == nil {
		if len(positional) > 0 {
			fmt.Fprintf(os.Stderr, "Error: unknown command \"%s\" for \"%s\"\n", positional[0], cmd.FullPath())
			if closest := cmd.findClosest(positional[0]); closest != "" {
				fmt.Fprintf(os.Stderr, "\nDid you mean this?\n\t%s\n\n", closest)
			}
			fmt.Fprintf(os.Stderr, "Run '%s --help' for usage.\n", cmd.rootPath())
			return 1
		}
		// No args: print help to stdout.
		fmt.Fprint(os.Stdout, cmd.Help)
		return 0
	}

	// Validate arg counts.
	// For exec, argument rules are special.
	if cmd.Name == "exec" && cmd.Parent != nil && cmd.Parent.Name == "chamber" {
		// first, at least one service
		if len(positional) < 1 {
			fmt.Fprintln(os.Stderr, "Error: at least one service must be specified: requires at least 1 arg(s), only received 0")
			cmd.printUsageAndFlags(os.Stderr)
			return 1
		}
		if !hasSep || len(after) < 1 {
			fmt.Fprintln(os.Stderr, "Error: must specify command to run. See usage: requires at least 1 arg(s), only received 0")
			cmd.printUsageAndFlags(os.Stderr)
			return 1
		}
	} else {
		if cmd.ExactArgs >= 0 && len(positional) != cmd.ExactArgs {
			msg := fmt.Sprintf("accepts %d arg(s), received %d", cmd.ExactArgs, len(positional))
			if cmd.ArgsErrPrefix != "" {
				msg = cmd.ArgsErrPrefix + ": " + msg
			}
			fmt.Fprintln(os.Stderr, "Error: "+msg)
			cmd.printUsageAndFlags(os.Stderr)
			return 1
		}
		if cmd.MinArgs >= 0 && len(positional) < cmd.MinArgs {
			msg := fmt.Sprintf("requires at least %d arg(s), only received %d", cmd.MinArgs, len(positional))
			if cmd.ArgsErrPrefix != "" {
				msg = cmd.ArgsErrPrefix + ": " + msg
			}
			fmt.Fprintln(os.Stderr, "Error: "+msg)
			cmd.printUsageAndFlags(os.Stderr)
			return 1
		}
	}

	// Initialize backend for commands that need it.
	if !cmd.NoBackend {
		if err := initBackend(); err != nil {
			fmt.Fprintln(os.Stderr, "Error: "+err.Error())
			return 1
		}
	}

	if err := cmd.Run(cmd, positional, after, hasSep); err != nil {
		fmt.Fprintln(os.Stderr, "Error: "+err.Error())
		return 1
	}
	return 0
}

// printUsageAndFlags prints the help for the command (to the supplied writer).
func (c *Command) printUsageAndFlags(w io.Writer) {
	fmt.Fprint(w, c.Help)
}

// rootPath returns the "chamber ..." path up to the root.
func (c *Command) rootPath() string {
	cur := c
	for cur.Parent != nil {
		cur = cur.Parent
	}
	return cur.Name
}

// findClosest returns a simple suggestion based on prefix match.
func (c *Command) findClosest(name string) string {
	for _, s := range c.Subs {
		if strings.HasPrefix(s.Name, name) {
			return s.Name
		}
	}
	return ""
}

// ---- Backend init ----

func initBackend() error {
	// Normalize backend name to upper for error reporting.
	b := strings.ToLower(globals.Backend)
	switch b {
	case "null":
		return nil
	case "ssm", "secretsmanager":
		// Accept but trying to use network will fail later; we don't have
		// credentials, so error out now to match the real binary's error mode.
		if _, err := retriesFromEnv(); err != nil {
			return fmt.Errorf("Failed to get secret store: %s", err.Error())
		}
		return fmt.Errorf("Failed to list store contents: could not initialize %s backend", strings.ToUpper(b))
	case "s3", "s3-kms":
		if globals.BackendS3Bucket == "" {
			return fmt.Errorf("Failed to get secret store: Must set bucket for s3 backend")
		}
		return fmt.Errorf("Failed to list store contents: could not initialize %s backend", strings.ToUpper(b))
	default:
		return fmt.Errorf("Failed to get secret store: invalid backend `%s`", strings.ToUpper(globals.Backend))
	}
}

