// parseJSONOrYAMLMap tries to parse the data as a simple map of string->string.
// Returns a non-nil error when parsing fails or the top-level structure is not a map.
func parseJSONOrYAMLMap(data []byte) (map[string]string, error) {
	// Trim whitespace to see what the first non-whitespace char is.
	trimmed := strings.TrimSpace(string(data))
	if trimmed == "" {
		return nil, fmt.Errorf("EOF")
	}

	// First try JSON.
	var obj map[string]interface{}
	if err := json.Unmarshal(data, &obj); err == nil {
		result := make(map[string]string, len(obj))
		for k, v := range obj {
			result[k] = fmt.Sprintf("%v", v)
		}
		return result, nil
	}

	// Very minimal YAML: key: value lines.
	first := trimmed[0]
