# Replace the subcommand extraction to scan args for first matching subcommand name.
# A subcommand name is a non-flag argument. But we can't know without parsing
# the flags which args are values to flags.
# Approach: for each position, if not a flag, check if it's a subcommand name.
# For flags requiring a value, skip the next arg.

python3 -c "
import re, sys
with open('main.go') as f:
    content = f.read()

old = '''func runCommand(cmd *Command, args []string) int {
\t// Extract subcommand path greedily
\tfor {
\t\tif len(args) > 0 {
\t\t\tsub := cmd.findSub(args[0])
\t\t\tif sub != nil {
\t\t\t\tcmd = sub
\t\t\t\targs = args[1:]
\t\t\t\tcontinue
\t\t\t}
\t\t}
\t\tbreak
\t}'''

new = '''func runCommand(cmd *Command, args []string) int {
\t// Extract subcommand path by scanning through args, respecting flags.
\tfor {
\t\tidx := findSubcommandIndex(cmd, args)
\t\tif idx < 0 {
\t\t\tbreak
\t\t}
\t\tsub := cmd.findSub(args[idx])
\t\tif sub == nil {
\t\t\tbreak
\t\t}
\t\t// Remove the subcommand name from args and recurse.
\t\tnewArgs := append([]string{}, args[:idx]...)
\t\tnewArgs = append(newArgs, args[idx+1:]...)
\t\tcmd = sub
\t\targs = newArgs
\t}'''

content = content.replace(old, new)

# Append findSubcommandIndex function
helper = '''

// findSubcommandIndex scans args to find the first non-flag positional
// that matches a subcommand name.
func findSubcommandIndex(cmd *Command, args []string) int {
\tfor i := 0; i < len(args); i++ {
\t\ta := args[i]
\t\tif a == \"--\" {
\t\t\treturn -1
\t\t}
\t\tif strings.HasPrefix(a, \"--\") && len(a) > 2 {
\t\t\tname := a[2:]
\t\t\teq := strings.Index(name, \"=\")
\t\t\tvar flagName string
\t\t\thasValue := eq >= 0
\t\t\tif hasValue {
\t\t\t\tflagName = name[:eq]
\t\t\t} else {
\t\t\t\tflagName = name
\t\t\t}
\t\t\tif flagName == \"help\" {
\t\t\t\tcontinue
\t\t\t}
\t\t\tf := cmd.findFlag(flagName, false)
\t\t\tif f == nil {
\t\t\t\treturn -1\n\t\t\t}
\t\t\tif f.Kind != KBool && !hasValue {
\t\t\t\ti++\n\t\t\t}\n\t\t\tcontinue\n\t\t}
\t\tif strings.HasPrefix(a, \"-\") && len(a) > 1 && a != \"-\" {
\t\t\tj := 1\n\t\t\tfor j < len(a) {
\t\t\t\tsh := string(a[j])
\t\t\t\tif sh == \"h\" { j++; continue }\n\t\t\t\tf := cmd.findFlag(sh, true)
\t\t\t\tif f == nil { return -1 }\n\t\t\t\tif f.Kind == KBool { j++; continue }\n\t\t\t\t// needs value\n\t\t\t\trest := a[j+1:]\n\t\t\t\tif strings.HasPrefix(rest, \"=\") { rest = rest[1:] }\n\t\t\t\tif rest == \"\" {\n\t\t\t\t\ti++\n\t\t\t\t}\n\t\t\t\tbreak\n\t\t\t}\n\t\t\tcontinue\n\t\t}
\t\tif cmd.findSub(a) != nil {\n\t\t\treturn i\n\t\t}\n\t\treturn -1\n\t}\n\treturn -1\n}\n'''

content += helper

with open('main.go', 'w') as f:
    f.write(content)
"
