package main

import (
	"fmt"
	"strings"
)

// runComplete implements a subset of cobra's __complete behavior.
// The actual command name passed by the caller is in os.Args[1], either
// "__complete" (with descriptions) or "__completeNoDesc" (without).
func runComplete(cmd *Command, args, rest []string, hasSep bool) error {
	// Determine descriptions on/off by which alias was used.
	showDesc := !wasInvokedAs("__completeNoDesc")

	// The last arg is what we're completing (may be empty).
	// Earlier args are already-entered tokens.
	// We'll navigate subcommands based on args.
	cur := rootCmd
	consumed := 0
	for i, a := range args[:len(args)-1] {
		_ = i
		if strings.HasPrefix(a, "-") {
			continue
		}
		sub := cur.findSub(a)
		if sub == nil {
			break
		}
		cur = sub
		consumed = i + 1
	}
	_ = consumed

	last := args[len(args)-1]

	// If the last token starts with "-", complete flags of the current command.
	if strings.HasPrefix(last, "-") {
		// Not implementing flag completion; just return default.
		fmt.Println(":0")
		fmt.Println("Completion ended with directive: ShellCompDirectiveDefault")
		return nil
	}

	// List subcommands that start with last token.
	if cur.hasVisibleSubs() {
		printed := false
		for _, s := range cur.Subs {
			if s.Hidden() || strings.HasPrefix(s.Name, "__") {
				continue
			}
			if strings.HasPrefix(s.Name, last) {
				if showDesc && s.ShortDesc() != "" {
					fmt.Printf("%s\t%s\n", s.Name, s.ShortDesc())
				} else {
					fmt.Println(s.Name)
				}
				printed = true
			}
		}
		_ = printed
		fmt.Println(":4")
		fmt.Println("Completion ended with directive: ShellCompDirectiveNoFileComp")
		return nil
	}

	fmt.Println(":0")
	fmt.Println("Completion ended with directive: ShellCompDirectiveDefault")
	return nil
}

func wasInvokedAs(name string) bool {
	// os.Args[1] is the subcommand typically.
	// A bit hacky: if the original args start with name, true.
	for _, a := range osArgs() {
		if a == name {
			return true
		}
	}
	return false
}

func (c *Command) Hidden() bool { return strings.HasPrefix(c.Name, "__") }
func (c *Command) hasVisibleSubs() bool {
	for _, s := range c.Subs {
		if !s.Hidden() {
			return true
		}
	}
	return false
}

// ShortDesc returns the first line of Help (matching cobra's `Short`).
func (c *Command) ShortDesc() string {
	// We don't track Short separately; derive from the Help text's first line.
	if c.Help == "" {
		return ""
	}
	line := c.Help
	if i := strings.Index(line, "\n"); i >= 0 {
		line = line[:i]
	}
	return line
}

EOF

